def semver_sort(versions):
    def parse_version(version):
        # Split build metadata
        if '+' in version:
            version, build = version.split('+', 1)
        else:
            build = None

        # Split pre-release
        if '-' in version:
            base, prerelease = version.split('-', 1)
        else:
            base = version
            prerelease = None

        # Parse base version
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_parts = prerelease.split('.')
            parsed_prerelease = []
            for part in prerelease_parts:
                if part.isdigit():
                    parsed_prerelease.append((0, int(part)))
                else:
                    parsed_prerelease.append((1, part))
        else:
            parsed_prerelease = None

        return (major, minor, patch, prerelease is None, parsed_prerelease)

    def compare_key(version):
        major, minor, patch, has_no_prerelease, prerelease = parse_version(version)
        # Returns tuple for sorting: (major, minor, patch, has_no_prerelease, prerelease)
        # has_no_prerelease=True sorts after has_no_prerelease=False (so we negate for sorting)
        # prerelease is either None (for no prerelease) or a list of (type, value) tuples
        if prerelease is None:
            prerelease_sort_key = (1,)  # Sorts after versions with prerelease
        else:
            prerelease_sort_key = (0, prerelease)  # Sorts before versions without prerelease

        return (major, minor, patch, prerelease_sort_key)

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

